// Watch embed preview and continuation views.
// Renders the small Watch-specific card contract generated by
// WatchEmbedPreviewMapper without importing iOS/macOS embed renderers.
// Tapping a card is handled by the parent shell so the detail screen can offer
// read-only Watch consumption with explicit iPhone continuation.
// Specification: specifications/features/apple-watch/specification.yml
// Assertions: apple-watch.chats.compact-layout, apple-watch.embeds.read-only-fullscreen

// ─── Web source ─────────────────────────────────────────────────────
// Svelte:  frontend/packages/ui/src/components/embeds/UnifiedEmbedPreview.svelte
//          frontend/packages/ui/src/components/embeds/UnifiedEmbedFullscreen.svelte
// Tokens:  ColorTokens.generated.swift, SpacingTokens.generated.swift
// ────────────────────────────────────────────────────────────────────

import SwiftUI
import MapKit
import CryptoKit
import WatchKit
import ImageIO

struct WatchEmbedPreviewCard: View {
    let model: WatchEmbedPreviewModel
    let onOpen: () -> Void

    var body: some View {
        Button(action: onOpen) {
            cardContent
        }
        .buttonStyle(.plain)
        .frame(width: CGFloat(WatchEmbedPreviewModel.cardWidth))
        .disabled(model.state == .processing)
        .accessibilityIdentifier("watch-embed-preview-\(model.family.rawValue)")
    }

    /// Watch always uses the user-approved mobile composition. The supplied
    /// Figma sheet frame places the real visual above a full-width app bar and
    /// centers metadata beneath it; no desktop icon/footer carousel is used.
    private var cardContent: some View {
        VStack(spacing: 0) {
            previewVisual
                .frame(width: CGFloat(WatchEmbedPreviewModel.cardWidth), height: 104)
                .clipped()
                .accessibilityIdentifier("watch-embed-visual-\(model.id)")
            Capsule().fill(gradient(forAppId: model.appId))
                .overlay { Icon(model.iconName, size: 24).foregroundStyle(Color.fontButton) }
                .frame(height: 38)
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(model.typeLabel)
                .accessibilityIdentifier("watch-embed-app-bar-\(model.id)")
            VStack(spacing: .spacing2) {
                Text(model.title).font(.omP.weight(.bold))
                    .foregroundStyle(Color.fontPrimary).multilineTextAlignment(.center).lineLimit(2)
                    .accessibilityIdentifier("watch-embed-title-\(model.id)")
                if let metadata = metadata {
                    Text(metadata).font(.omSmall.weight(.semibold))
                        .foregroundStyle(Color.fontSecondary).multilineTextAlignment(.center).lineLimit(2)
                        .accessibilityIdentifier("watch-embed-metadata-\(model.id)")
                }
                if model.state != .ready { WatchEmbedStatePill(state: model.state) }
            }
            .frame(maxWidth: .infinity).padding(.spacing4)
        }
        .frame(width: CGFloat(WatchEmbedPreviewModel.cardWidth))
        .frame(minHeight: CGFloat(WatchEmbedPreviewModel.cardHeight))
        .background(Color.grey0)
        .clipShape(RoundedRectangle(cornerRadius: .radius6, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: .radius6, style: .continuous)
            .stroke(model.state == .error ? Color.error : Color.grey25, lineWidth: 1))
    }

    private var metadata: String? {
        if case .table(_, _, let count) = model.visual, let count {
            return WatchLocalization.text("embeds.watch_sheet_cells")
                .replacingOccurrences(of: "{count}", with: String(count))
        }
        return model.detail ?? model.subtitle
    }

    @ViewBuilder private var previewVisual: some View {
        if model.state == .processing {
            ProgressView().tint(Color.fontPrimary).frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if model.detailContent.imageData != nil || model.detailContent.imageURL != nil {
            WatchEmbedThumbnail(content: model.detailContent)
        } else {
            switch model.visual {
            case .table(let headers, let rows, _):
                VStack(spacing: 0) {
                    tableRow(headers, index: 1, isHeader: true)
                    ForEach(Array(rows.enumerated()), id: \.offset) { index, row in
                        tableRow(row, index: index + 2, isHeader: false)
                    }
                    Spacer(minLength: 0)
                }
                .background(Color.grey10)
            case .code(let lines):
                VStack(alignment: .leading, spacing: .spacing2) {
                    ForEach(Array(lines.enumerated()), id: \.offset) { _, line in
                        Text(line).font(.system(size: 12, design: .monospaced))
                            .foregroundStyle(Color.fontPrimary).lineLimit(1)
                    }
                    Spacer(minLength: 0)
                }.padding(.spacing4).frame(maxWidth: .infinity, alignment: .leading)
            case .text(let lines):
                VStack(alignment: .leading, spacing: .spacing3) {
                    ForEach(Array(lines.enumerated()), id: \.offset) { _, line in
                        Text(line).font(.omSmall).foregroundStyle(Color.fontPrimary).lineLimit(2)
                    }
                    Spacer(minLength: 0)
                }.padding(.spacing4).frame(maxWidth: .infinity, alignment: .leading)
            case .symbol:
                Icon(model.state == .error ? "warning" : model.iconName, size: 36)
                    .foregroundStyle(Color.fontSecondary)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color.grey10)
                    .accessibilityHidden(true)
            }
        }
    }

    private func tableRow(_ values: [String], index: Int, isHeader: Bool) -> some View {
        HStack(spacing: 0) {
            Text(String(index)).font(.omTiny).foregroundStyle(Color.fontSecondary)
                .frame(width: 20, height: 26)
                .background(Color.grey20)
            ForEach(Array(values.enumerated()), id: \.offset) { _, cell in
                Text(cell).font(.omXs.weight(isHeader ? .semibold : .regular))
                    .foregroundStyle(Color.fontPrimary).lineLimit(1)
                    .frame(maxWidth: .infinity, minHeight: 26, alignment: .leading)
                    .padding(.horizontal, .spacing2)
                    .overlay(Rectangle().stroke(Color.grey25, lineWidth: 0.5))
            }
        }
    }

    private func gradient(forAppId appId: String) -> LinearGradient {
        switch appId {
        case "web": return .appWeb
        case "videos": return .appVideos
        case "code": return .appCode
        case "maps": return .appMaps
        case "travel": return .appTravel
        case "shopping": return .appShopping
        case "weather": return .appWeather
        case "reminder": return .appReminder
        case "images": return .appImages
        case "photos": return .appPhotos
        case "audio": return .appAudio
        case "pdf": return .appPdf
        case "events": return .appEvents
        case "docs": return .appDocs
        case "sheets": return .appSheets
        case "mindmaps": return .appMindmaps
        case "news": return .appNews
        case "health": return .appHealth
        case "nutrition": return .appNutrition
        case "fitness": return .appFitness
        case "design": return .appDesign
        case "electronics": return .appElectronics
        case "home": return .appHome
        case "business": return .appBusiness
        case "finance": return .appFinance
        case "social_media": return .appSocial_media
        case "models3d": return .app3dmodels
        case "calendar": return .appCalendar
        case "mail": return .appMail
        default: return .primary
        }
    }
}

/// A compact, explicit continuation keeps unavailable payloads actionable
/// without claiming that their full content can be opened on Watch.
struct WatchEmbedContinuationView: View {
    let model: WatchEmbedPreviewModel
    let onOpenDevice: () -> Void
    let onClose: () -> Void

    var body: some View {
        ZStack {
            Color.grey100.opacity(0.96).ignoresSafeArea()
            VStack(spacing: .spacing3) {
                Text(model.title)
                    .font(.omP.weight(.bold)).foregroundStyle(Color.grey0)
                    .multilineTextAlignment(.center).lineLimit(2)
                Button(action: onOpenDevice) {
                    Text(WatchLocalization.text("watch.hub.open_on_phone"))
                        .font(.omSmall.weight(.semibold)).foregroundStyle(Color.fontButton)
                        .frame(maxWidth: .infinity, minHeight: 34)
                        .background(Color.buttonPrimary, in: Capsule())
                }
                .buttonStyle(.plain)
                .accessibilityIdentifier("watch-embed-open-device")
                Button(action: onClose) {
                    Text(WatchLocalization.text("common.close"))
                        .font(.omSmall).foregroundStyle(Color.grey0)
                        .frame(maxWidth: .infinity, minHeight: 34)
                        .background(Color.grey80, in: Capsule())
                }
                .buttonStyle(.plain)
                .accessibilityIdentifier("watch-embed-continuation-close")
            }
            .padding(.spacing4).frame(maxWidth: 178)
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("watch-embed-continuation")
    }
}

private struct WatchEmbedStatePill: View {
    let state: WatchEmbedPreviewState

    var body: some View {
        Text(label)
            .font(.omMicro)
            .foregroundStyle(foreground)
            .padding(.horizontal, .spacing2)
            .padding(.vertical, 1)
            .background(background, in: Capsule())
    }

    private var label: String {
        switch state {
        case .ready: return WatchLocalization.text("common.continue")
        case .processing: return WatchLocalization.text("common.processing")
        case .error: return WatchLocalization.text("embeds.application_preview_failed")
        case .unavailable: return WatchLocalization.text("embeds.watch_preview_unavailable")
        }
    }

    private var foreground: Color {
        switch state {
        case .ready, .processing, .unavailable: return Color.fontPrimary
        case .error: return Color.error
        }
    }

    private var background: Color {
        switch state {
        case .ready: return Color.buttonPrimary.opacity(0.35)
        case .processing, .unavailable: return Color.grey20
        case .error: return Color.error.opacity(0.16)
        }
    }
}

private struct WatchEmbedAccountIDKey: EnvironmentKey { static let defaultValue: String? = nil }
extension EnvironmentValues {
    var watchEmbedAccountID: String? {
        get { self[WatchEmbedAccountIDKey.self] }
        set { self[WatchEmbedAccountIDKey.self] = newValue }
    }
}

/// Fetch only a visible thumbnail on demand, using a bounded cookie-free
/// transport. Cached bytes remain encrypted under the authenticated owner.
private struct WatchEmbedThumbnail: View {
    let content: WatchEmbedDetailContent
    @Environment(\.watchEmbedAccountID) private var accountID
    @State private var bitmap: UIImage?
    @State private var failed = false
    var body: some View {
        Group {
            if let bitmap { Image(uiImage: bitmap).resizable().scaledToFit() }
            else if failed {
                Text(WatchLocalization.text("embeds.watch_preview_unavailable"))
                    .font(.omSmall).foregroundStyle(Color.fontSecondary)
            } else { ProgressView().tint(Color.fontPrimary) }
        }
        .accessibilityIdentifier("watch-embed-thumbnail")
        .task(id: content.imageURL?.absoluteString ?? "inline-thumbnail") {
            bitmap = nil; failed = false
            let generation = WatchChatAccountLifecycle.generation
            let profile = ServerProfile.current()
            @MainActor func current() -> Bool {
                guard !Task.isCancelled,
                      generation == WatchChatAccountLifecycle.generation else { return false }
                return profile == ServerProfile.current()
            }
            if let data = content.imageData, let image = Self.decodeThumbnail(data), current() { bitmap = image; return }
            guard let url = content.imageURL, let accountID else { failed = true; return }
            let scope = WatchWorkflowDetailScope.capture(accountID: accountID)
            let key = "thumbnail:" + SHA256.hash(data: Data(url.absoluteString.utf8)).map { String(format: "%02x", $0) }.joined()
            do {
                guard let master = try await CryptoManager.shared.loadMasterKey(for: accountID), current() else { throw CancellationError() }
                if let cached = await WatchHubOfflineCache.shared.load(key: key, scope: scope, masterKey: master),
                   cached.count <= 512_000, let image = Self.decodeThumbnail(cached), current() { bitmap = image; return }
                let configuration = URLSessionConfiguration.ephemeral
                configuration.httpCookieStorage = nil; configuration.httpShouldSetCookies = false
                configuration.urlCache = nil; configuration.timeoutIntervalForRequest = 15
                configuration.timeoutIntervalForResource = 15
                let session = URLSession(configuration: configuration)
                defer { session.invalidateAndCancel() }
                let (bytes, response) = try await session.bytes(from: url)
                guard let response = response as? HTTPURLResponse, (200..<300).contains(response.statusCode),
                      response.expectedContentLength <= 512_000 else { throw URLError(.dataLengthExceedsMaximum) }
                var data = Data()
                for try await byte in bytes {
                    guard data.count < 512_000, data.count % 4096 != 0 || current() else { throw CancellationError() }
                    data.append(byte)
                }
                guard current(), let image = Self.decodeThumbnail(data) else { throw URLError(.cannotDecodeContentData) }
                try? await WatchHubOfflineCache.shared.save(data, key: key, scope: scope, masterKey: master)
                guard current() else { return }
                bitmap = image
            } catch { if current() { failed = true } }
        }
    }
    private static func decodeThumbnail(_ data: Data) -> UIImage? {
        guard data.count <= 512_000, let source = CGImageSourceCreateWithData(data as CFData, nil),
              let image = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceThumbnailMaxPixelSize: 512,
                kCGImageSourceCreateThumbnailWithTransform: true
              ] as CFDictionary) else { return nil }
        return UIImage(cgImage: image)
    }

}

/// Fullscreen consumes hydrated content only. No editing, downloads, playback,
/// navigation to arbitrary URLs, or workflow execution controls are introduced.
struct WatchEmbedFullscreenView: View {
    let model: WatchEmbedPreviewModel
    let onOpenDevice: (WatchEmbedPreviewModel) -> Void
    let onClose: () -> Void
    @State private var child: WatchEmbedPreviewModel?
    @AppStorage("watch.transcript.zoom") private var zoomLevel = 0
    private let markdown: [WatchRenderedMarkdownBlock]

    init(model: WatchEmbedPreviewModel, onOpenDevice: @escaping (WatchEmbedPreviewModel) -> Void, onClose: @escaping () -> Void) {
        self.model = model; self.onOpenDevice = onOpenDevice; self.onClose = onClose
        markdown = WatchMarkdownParser.blocks(model.detailContent.text ?? "").map(WatchRenderedMarkdownBlock.init)
    }

    private func tableRow(_ values: [String], heading: Bool) -> some View {
        HStack(spacing: 0) {
            ForEach(Array(values.enumerated()), id: \.offset) { _, value in
                Text(value).font(.omSmall.weight(heading ? .bold : .regular))
                    .frame(width: 110, alignment: .leading).padding(.spacing2)
                    .overlay(Rectangle().stroke(Color.grey60, lineWidth: 0.5))
            }
        }
    }

    var body: some View {
        ZStack {
            VStack(spacing: .spacing2) {
                HStack {
                    Button(action: onClose) {
                        Icon("back", size: .iconSizeSm)
                            .frame(width: 34, height: 34)
                            // The Watch status window owns the top 38 points.
                            // Match the production chat header: keep the glyph
                            // at the top, with a real hit target extending below
                            // that window into the pinned header's front layer.
                            .frame(width: 34, height: 76, alignment: .top)
                            .contentShape(Rectangle())
                    }
                        .buttonStyle(.plain).padding(.bottom, -42)
                        .accessibilityLabel(WatchLocalization.text("common.close"))
                        .accessibilityIdentifier("watch-embed-continuation-close")
                    Text(model.title).font(.omSmall.weight(.bold)).lineLimit(2)
                        .frame(maxWidth: .infinity, alignment: .leading)
                }
                .frame(height: 34, alignment: .top)
                .background(Color.grey100)
                .zIndex(1)
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: .spacing3) {
                        if model.detailContent.imageData != nil || model.detailContent.imageURL != nil {
                            WatchEmbedThumbnail(content: model.detailContent).frame(maxWidth: .infinity, minHeight: 104)
                        }
                        if let latitude = model.detailContent.latitude, let longitude = model.detailContent.longitude {
                            Map(initialPosition: .region(MKCoordinateRegion(
                                center: CLLocationCoordinate2D(latitude: latitude, longitude: longitude),
                                span: MKCoordinateSpan(latitudeDelta: 0.015, longitudeDelta: 0.015)))) {
                                Marker(model.title, coordinate: CLLocationCoordinate2D(latitude: latitude, longitude: longitude))
                            }
                            .frame(height: 140).clipShape(RoundedRectangle(cornerRadius: .radius4))
                            .accessibilityIdentifier("watch-embed-read-only-map")
                        }
                        if model.detailContent.isCode, let code = model.detailContent.text {
                            ScrollView(.horizontal) { Text(code).modifier(WatchTranscriptType(monospaced: true, zoomLevel: zoomLevel)) }
                                .accessibilityIdentifier("watch-embed-fullscreen-code")
                        } else if !model.detailContent.tableHeaders.isEmpty {
                            ScrollView(.horizontal) {
                                LazyVStack(alignment: .leading, spacing: 0) {
                                    tableRow(model.detailContent.tableHeaders, heading: true)
                                    ForEach(Array(model.detailContent.tableRows.enumerated()), id: \.offset) { _, values in
                                        tableRow(values, heading: false)
                                    }
                                }
                            }.accessibilityIdentifier("watch-embed-fullscreen-table")
                        } else if !markdown.isEmpty {
                            WatchMarkdownContent(blocks: markdown, zoomLevel: zoomLevel)
                                .accessibilityIdentifier("watch-embed-fullscreen-text")
                        }
                        ForEach(model.detailContent.children) { preview in
                            WatchEmbedPreviewCard(model: preview) { child = preview }
                        }
                        if model.detailContent == .empty || model.state == .unavailable {
                            Text(WatchLocalization.text("embeds.watch_preview_unavailable")).font(.omSmall)
                                .accessibilityIdentifier("watch-embed-fullscreen-unavailable")
                        }
                        Button { onOpenDevice(model) } label: {
                            Text(WatchLocalization.text("watch.hub.open_on_phone"))
                                .font(.omSmall.weight(.semibold)).frame(maxWidth: .infinity, minHeight: 34)
                                .background(Color.buttonPrimary, in: Capsule())
                        }
                        .buttonStyle(.plain).accessibilityIdentifier("watch-embed-open-device")
                    }
                }
                .clipped().contentShape(Rectangle())
                .accessibilityIdentifier("watch-embed-fullscreen-scroll")
            }
            .padding(.spacing3).background(Color.grey100).foregroundStyle(Color.grey0)
            .accessibilityHidden(child != nil).allowsHitTesting(child == nil)
            if let child {
                WatchEmbedFullscreenView(model: child, onOpenDevice: onOpenDevice, onClose: { self.child = nil })
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity).background(Color.grey100).ignoresSafeArea(edges: .top)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("watch-embed-continuation")
    }
}
